package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.PostcodeRange;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Rejects a create-owner request whose supplied postcode is out of range for the owner's city
 * region, responding 400 via {@link InvalidPostcodeException}. Postcode is validated only WHEN
 * PRESENT: an absent postcode is accepted, keeping the request contract backward-compatible. The
 * 4-digit format is already enforced by bean validation on the request body, so by the time this
 * step runs a present postcode is exactly four digits; region membership is checked against the
 * pinned {@link PostcodeRange} table.
 */
public class RequirePostcodeInRegion {

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null) {
            return;
        }
        if (!PostcodeRange.isValidForCity(request.getCity(), postcode)) {
            throw new InvalidPostcodeException(request.getCity(), postcode);
        }
    }
}

